const SKILL_TREE_UF_BOUNDS_10C = {
  'seapony|damageTakenMult':  { min:-0.4,  max:0.5 },
  'seapony|radius':           { min:-2,    max:2 },
  'seapony|baseRangeTiles':   { min:0,     max:1.5 },
  'ponybot|damageTakenMult':  { min:-0.15, max:0 },
  'ponybot|radius':           { min:-2,    max:2 },
  'ponybot|baseRangeTiles':   { min:0,     max:1.5 },
  'griffin|damageTakenMult':  { min:-0.5,  max:0.5 },
  'griffin|radius':           { min:-2,    max:2 },
  'griffin|baseRangeTiles':   { min:0,     max:1.5 },
  'griffin|chargeTime':       { min:0,     max:1.5 },
};

function ST10C(classId, stat, amount, perRank){
  const e = { type:'stat', classId, stat, amount };
  if (perRank != null) e.perRank = perRank;
  return e;
}
function UF10C(classId, field, amount){
  const b = SKILL_TREE_UF_BOUNDS_10C[classId + '|' + field];
  return { type:'uniqueField', classId, field, amount, min:b.min, max:b.max };
}
function FL10C(classId, field, value){ return { type:'uniqueFlag', classId, field, value }; }
function SY10C(classId, stat, perOwned, tag){ return { type:'synergyStat', classId, stat, perOwned, tag }; }

